python3 - <<'EOF'
import hashlib, hmac, json, os, tempfile
from pathlib import Path
from carbon_market import signal_ingest as si
from carbon_market import signals

tmp = tempfile.mkdtemp()
sigp = os.path.join(tmp, "signals.json"); trustp = os.path.join(tmp, "trust.json"); ledp = os.path.join(tmp, "ingest.json")
secret_hex = "aa"*32; secret = bytes.fromhex(secret_hex)
trust = {"src-a": {"key_id": "k1", "key": secret_hex, "regions": ["eu-north","us-west"], "valid_from": 0, "valid_until": 1000}}
Path(trustp).write_bytes(si._serialize_trust(trust))

def envelope(source, key_id, seq, signal, secret):
    csig = {f: signal[f] for f in ("region","observed","expires","mix","unit_cost","carbon_intensity")}
    csig["mix"] = {k: csig["mix"][k] for k in sorted(csig["mix"])}
    msg = json.dumps([source,key_id,seq,csig], ensure_ascii=False, separators=(",",":")).encode()
    return {"source":source,"key_id":key_id,"sequence":seq,"signal":signal,"signature":hmac.new(secret,msg,hashlib.sha256).hexdigest()}

s1 = {"region":"eu-north","observed":10,"expires":100,"mix":{"wind":4000,"solar":6000},"unit_cost":3,"carbon_intensity":7}
env = envelope("src-a","k1",1,s1,secret)
r,c = si.ingest(sigp,trustp,ledp,env,"call-key-1"); assert c and r["signal_version"]==1

# properly signed DIFFERENT envelope under same ingest key -> ValueError
env5 = envelope("src-a","k1",5,{**s1,"observed":50},secret)
try:
    si.ingest(sigp,trustp,ledp,env5,"call-key-1"); print("FAIL conflict")
except ValueError: print("same-key different envelope -> ValueError ok")

# non-increasing seq (properly signed)
try:
    si.ingest(sigp,trustp,ledp,envelope("src-a","k1",1,s1,secret),"other-key"); print("FAIL seqreuse")
except ValueError: print("sequence reuse other key -> ValueError ok")

# tampered unsigned field -> PermissionError
bad = dict(env); bad["sequence"]=5
try:
    si.ingest(sigp,trustp,ledp,bad,"call-key-1"); print("FAIL tamper")
except PermissionError: print("tampered -> PermissionError ok")

# wrong key secret signature
try:
    si.ingest(sigp,trustp,ledp,envelope("src-a","k1",3,{**s1,"observed":30},b"\x00"*32),"k3"); print("FAIL sig")
except PermissionError: print("bad signature -> PermissionError ok")

# unknown source / key id
for e in [envelope("src-x","k1",3,{**s1,"observed":30},secret), envelope("src-a","k9",3,{**s1,"observed":30},secret)]:
    try: si.ingest(sigp,trustp,ledp,e,"k"); print("FAIL")
    except PermissionError: pass
print("unknown source/key_id -> PermissionError ok")

# region + window
for s in [{**s1,"region":"ap-south","observed":30},{**s1,"observed":1001},{**s1,"observed":-1 and 0}]:
    pass
try: si.ingest(sigp,trustp,ledp,envelope("src-a","k1",3,{**s1,"region":"ap","observed":30},secret),"k")
except ValueError: print("region ValueError ok")
try: si.ingest(sigp,trustp,ledp,envelope("src-a","k1",3,{**s1,"observed":1001},secret),"k")
except ValueError: print("window ValueError ok")

# missing trust
try: si.ingest(sigp,os.path.join(tmp,"nope.json"),ledp,env,"k")
except FileNotFoundError: print("missing trust -> FileNotFoundError ok")

# missing parent for ledger
try: si.ingest(sigp,trustp,os.path.join(tmp,"nodir","x.json"),env,"k")
except FileNotFoundError: print("missing ledger parent -> FileNotFoundError ok")

# canonical check on trust
p2=os.path.join(tmp,"trust2.json"); Path(p2).write_text(json.dumps(trust,indent=2))
try: si.ingest(sigp,p2,ledp,envelope("src-a","k1",6,{**s1,"observed":60},secret),"k")
except ValueError: print("noncanonical trust -> ValueError ok")

# no key material in ledger file
raw=Path(ledp).read_text(); assert secret_hex not in raw
print("no secret in ledger ok")
print(raw)
EOF

